files.hooks/register.ts:
import type { EngineInterface, PluginOptions, Register, ToolCallResult } from "claude-code";
import { apply, FLOWPLAN_TOOL, initialState, type GraphState } from "../graph/reduce.ts";
import { snapshot } from "../graph/snapshot.ts";
import type { GraphEvent, Layout, Snapshot, TerminalInfo } from "../graph/types.ts";
import { alerts, describeRequest, FLOWPLAN_SPEC, nudgeText, promptTitle, statusLine, summarize } from "../live/present.ts";
import { appNotice, autoUpdate, HELP, init, newerVersion, openInBackground, parseArgs, uninstall, type InstallContext } from "../live/install.ts";
import { homeOf, platformOf, type Platform } from "../live/platform.ts";
import { rebuildEvents } from "../live/rebuild.ts";
import { overlayClient, type OverlayClient, type OverlayIo } from "../live/transport.ts";
import { parentPid } from "../live/windows.ts";
import { omitKeys, Recording, trim } from "../recorder/recording.ts";

// The live mod: every hook below observes one engine event, passes it on
// untouched, and feeds it to the graph (mod/graph). Each change publishes a
// snapshot to the overlay app (mod/live/transport.ts) and to
// ~/.flowctl/sessions/<id>.json, and refreshes the status line. Nothing here
// may fail or slow down a call: all I/O is fire-and-forget.
//
// The events reach the graph in the same shape the recorder stores them, so
// the fixtures in fixtures/ replay exactly what a live session sees.

// Tools whose input and result the graph reads. Every other tool call keeps
// only its name, agent and outcome, so file contents and commands stay out.
const GRAPH_TOOLS = new Set([
  "TaskCreate",
  "TaskUpdate",
  "TaskGet",
  "TaskList",
  "TaskStop",
  "TodoWrite",
  "Agent",
  "AskUserQuestion",
  "SendMessage",
  FLOWPLAN_TOOL
]);

// Fields of classic events, at any depth, that carry prompts, the model's
// text, tool payloads or paths.
const CLASSIC_DROPPED = new Set([
  "prompt",
  "delta",
  "tool_input",
  "tool_response",
  "transcript_path",
  "agent_transcript_path",
  "scratchpad_dir",
  "cwd",
  "last_assistant_message"
]);

const PUBLISH_DELAY_MS = 100;
/**
 * How long an "ask" waits before it turns the step yellow: longer than the
 * auto-mode classifier takes to decide, short next to a person deciding.
 */
const ASK_WAIT_MS = 5000;
const RECORD_FLUSH_DELAY_MS = 500;

type Entry = Omit<GraphEvent, "seq">;

interface Settings {
  errorThreshold: number;
  nudge: boolean;
  autoOpenOverlay: boolean;
  autoUpdateApp: boolean;
  recordEvents: boolean;
}

let settings: Settings = { errorThreshold: 3, nudge: true, autoOpenOverlay: true, autoUpdateApp: true, recordEvents: false };
let graph: GraphState = initialState();
let flowctlDir: string | undefined;
let overlay: OverlayClient | undefined;
// Readers drop a snapshot whose seq is not above the last one, and a reload
// of this module starts its variables over: counting from the clock keeps
// seq growing across reloads.
let seq = Date.now();
let lastSnapshot: Snapshot | undefined;
let lastLayout: Layout | undefined;
let publishScheduled = false;
let planTool = "TaskCreate";
let terminal: TerminalInfo | undefined;

// Recorder (opt-in): the same events, kept as fixtures-to-be.
let recording: Recording | undefined;
let recordingSession: string | undefined;
let recordScheduled = false;
let recordFlushing: Promise<void> = Promise.resolve();

function readSettings(options: PluginOptions): Settings {
  const threshold = Number(options["errorThreshold"]);
  return {
    errorThreshold: Number.isFinite(threshold) && threshold >= 1 ? threshold : 3,
    // On unless turned off: without it the agent rarely declares a plan.
    nudge: options["nudge"] !== false,
    autoOpenOverlay: options["autoOpenOverlay"] !== false,
    autoUpdateApp: options["autoUpdateApp"] !== false,
    recordEvents: options["recordEvents"] === true
  };
}

/** One engine event: into the graph, into the recording, then out to the surfaces. */
function observe($: EngineInterface, event: string, fields: Omit<Entry, "t" | "event">): void {
  try {
    const entry: Entry = { t: Date.now(), event, ...fields };
    apply(graph, entry);
    if (settings.recordEvents) {
      record($, entry);
    }
    schedulePublish($);
  } catch {
    // A lost event is better than a failed hook.
  }
}

function schedulePublish($: EngineInterface): void {
  if (publishScheduled) {
    return;
  }
  publishScheduled = true;
  $.clock.after(PUBLISH_DELAY_MS, () => {
    publishScheduled = false;
    publish($);
  });
}

function publish($: EngineInterface): void {
  try {
    seq += 1;
    const next = snapshot(graph, {
      seq,
      now: Date.now(),
      ...(lastLayout ? { previous: lastLayout } : {}),
      ...(terminal ? { terminal } : {})
    });
    lastLayout = next.layout;
    for (const line of alerts(lastSnapshot, next)) {
      $.ui.toast(line);
    }
    lastSnapshot = next;
    $.ui.status(statusLine(next));
    if (flowctlDir === undefined || next.sessionId === "") {
      return;
    }
    const body = JSON.stringify(next);
    void overlay?.request("POST", "/snapshot", body).catch(() => undefined);
    void $.fs.write(`${flowctlDir}/sessions/${next.sessionId}.json`, body).catch(() => undefined);
  } catch {
    // The next event publishes again.
  }
}

/** The host's platform: Windows by its OS variable, else what uname says. */
async function hostPlatform($: EngineInterface): Promise<Platform> {
  const osName = await $.env.get("OS");
  const uname = osName === "Windows_NT" ? "" : await $.process.run(["uname", "-s"]).then((run) => run.stdout).catch(() => "");
  return platformOf(osName, uname);
}

/** The host's file and HTTP calls, for the overlay client. */
function overlayIo($: EngineInterface): OverlayIo {
  return {
    fetch: (url, init) => $.http.fetch(url, init),
    read: (path) => $.fs.read(path),
    mtime: async (path) => (await $.fs.stat(path)).mtimeMs
  };
}

/**
 * Where this session runs: the terminal app, its tty and its own ids, so the
 * overlay can bring this terminal forward when a node is clicked.
 */
async function findTerminal($: EngineInterface, platform: Platform): Promise<TerminalInfo> {
  // $.env.get takes literal names, so the variables the mod reads are listed.
  const read = (value: string | undefined) => (value === undefined || value === "" ? undefined : value);
  const ids: Record<string, string> = {};
  const iterm = read(await $.env.get("ITERM_SESSION_ID").catch(() => undefined));
  const apple = read(await $.env.get("TERM_SESSION_ID").catch(() => undefined));
  const maestri = read(await $.env.get("MAESTRI_TERMINAL_ID").catch(() => undefined));
  const windowsTerminal = read(await $.env.get("WT_SESSION").catch(() => undefined));
  if (iterm !== undefined) ids["ITERM_SESSION_ID"] = iterm;
  if (apple !== undefined) ids["TERM_SESSION_ID"] = apple;
  if (maestri !== undefined) ids["MAESTRI_TERMINAL_ID"] = maestri;
  if (windowsTerminal !== undefined) ids["WT_SESSION"] = windowsTerminal;
  const app = read(await $.env.get("__CFBundleIdentifier").catch(() => undefined));
  const program = read(await $.env.get("TERM_PROGRAM").catch(() => undefined));
  // The shell's parent is this Claude Code process: its pid, and on Unix its
  // tty, which is the session's (Windows has no tty).
  const [pidText = "", tty = ""] = await $.process
    .run(platform === "win32" ? parentPid() : ["sh", "-c", "echo $PPID; ps -o tty= -p $PPID"])
    .then((run) => run.stdout.trim().split(/\s+/))
    .catch(() => []);
  const pid = Number(pidText);
  return {
    ...(app !== undefined ? { app } : {}),
    ...(program !== undefined ? { program } : {}),
    ...(tty !== "" && tty !== "??" ? { tty } : {}),
    ...(Number.isInteger(pid) && pid > 1 ? { pid } : {}),
    ...(Object.keys(ids).length > 0 ? { ids } : {})
  };
}

/**
 * Replays the plan the transcript already holds: after a reload of the mod
 * (its memory starts over) or when a session is resumed, the graph would
 * otherwise be empty until the agent touched its plan again.
 */
async function rebuildFromTranscript($: EngineInterface): Promise<void> {
  const messages = await $.session.messages();
  if (!Array.isArray(messages) || messages.length === 0) {
    return;
  }
  const agents = await $.agent.list().catch(() => []);
  const events = rebuildEvents(messages, { flowPlanTool: FLOWPLAN_TOOL, agents, at: Date.now() });
  if (events.length === 0) {
    return;
  }
  const { sessionId, cwd } = graph;
  graph = initialState({ errorThreshold: settings.errorThreshold });
  graph.sessionId = sessionId;
  graph.cwd = cwd;
  for (const event of events) {
    apply(graph, event);
  }
  schedulePublish($);
}

/** The newer plugin version already announced, and when the folder was last looked at. */
let announced: string | undefined;
let lookedAt = 0;
/** At a session start, then at most once a day while it stays open. */
const LOOK_EVERY_MS = 24 * 60 * 60 * 1000;

/**
 * A session that stays open keeps the plugin it started with. When a newer
 * version lands next to it (an update from /plugin, in this session or
 * another), say once that it, and the overlay app with it, comes with the
 * next session start or /reload-plugins. Only the local plugin folder is
 * read; nothing goes out.
 */
async function lookForNewer($: EngineInterface): Promise<void> {
  const now = Date.now();
  if (now - lookedAt < LOOK_EVERY_MS) return;
  lookedAt = now;
  const root = $.plugin.root.replace(/[\\/]+$/, "");
  const parent = root.slice(0, Math.max(root.lastIndexOf("/"), root.lastIndexOf("\\")));
  if (parent === "") return;
  const entries = await $.fs.list(parent);
  const newer = newerVersion(entries.filter((entry) => entry.kind === "dir").map((entry) => entry.name));
  if (newer === undefined || newer === announced) return;
  announced = newer;
  $.ui.toast(`FlowCTL ${newer} is ready: the plugin and the overlay app update with the next session start, or now with /reload-plugins.`);
}

/** Whether this load of the plugin has done its start (the session may have started before a reload). */
let started = false;

/**
 * At a session start: an app older than this mod is updated (it is opened
 * again after), whether or not it is running; else the app is opened when it
 * is installed and not already listening.
 */
async function startOverlay($: EngineInterface, client: OverlayClient): Promise<void> {
  if (settings.autoUpdateApp) {
    const updated = await autoUpdate(await installContext($)).catch(() => undefined);
    if (updated !== undefined) {
      $.ui.toast(updated);
      $.ui.status(undefined);
      if (!updated.includes("could not be updated")) return;
    }
  }
  if (settings.autoOpenOverlay) {
    await openOverlay($, client);
  }
}

/** Opens the overlay app when it is installed and not already listening. */
async function openOverlay($: EngineInterface, client: OverlayClient): Promise<void> {
  const alive = await client.request("GET", "/health");
  if (alive) {
    return;
  }
  // Not installed, or older than this mod: say how to fix it, once per session.
  const ctx = await installContext($);
  const notice = await appNotice(ctx).catch(() => undefined);
  if (notice) {
    $.ui.toast(notice);
    if (notice.includes("not installed")) return;
  }
  await openInBackground(ctx).catch(() => undefined);
}

async function installContext($: EngineInterface): Promise<InstallContext> {
  const releaseBase = await $.env.get("FLOWCTL_RELEASE_BASE");
  const localAppData = await $.env.get("LOCALAPPDATA");
  const appData = await $.env.get("APPDATA");
  const temp = (await $.env.get("TEMP")) ?? (await $.env.get("TMP"));
  return {
    home: homeOf(await $.env.get("HOME"), await $.env.get("USERPROFILE")),
    platform: await hostPlatform($),
    ...(localAppData ? { localAppData } : {}),
    ...(appData ? { appData } : {}),
    ...(temp ? { temp } : {}),
    ...(releaseBase ? { releaseBase } : {}),
    run: (argv, timeoutMs) =>
      $.process.run(argv, timeoutMs === undefined ? {} : { timeoutMs }).catch((error: unknown) => ({ exitCode: 127, stdout: "", stderr: String(error) })),
    progress: (line) => $.ui.status(line)
  };
}

/**
 * The plan source (docs/roadmap-agent-graph.md, Phase 1 gate): the session's
 * own task tools when it has them, else the FlowPlan tool this mod serves.
 */
async function choosePlanTool($: EngineInterface): Promise<void> {
  const tools = await $.tool.list();
  if (tools.some((tool) => tool.name === "TaskCreate")) {
    planTool = "TaskCreate";
    return;
  }
  const registered = await $.tool.register(FLOWPLAN_SPEC);
  planTool = registered.tool;
}

function record($: EngineInterface, entry: Entry): void {
  if (flowctlDir === undefined) {
    return;
  }
  const sessionId = graph.sessionId;
  if (sessionId !== undefined && sessionId !== recordingSession) {
    flushRecording($);
    recordingSession = sessionId;
    recording = new Recording(`${flowctlDir}/recordings/${sessionId}`, String(Date.now()));
  }
  recording?.add(entry);
  if (!recordScheduled) {
    recordScheduled = true;
    $.clock.after(RECORD_FLUSH_DELAY_MS, () => {
      recordScheduled = false;
      void flushRecording($);
    });
  }
}

function flushRecording($: EngineInterface): Promise<void> {
  // Taken now, so a session switch right after cannot redirect these writes.
  const writes = recording?.flush() ?? [];
  recordFlushing = recordFlushing.then(async () => {
    for (const write of writes) {
      await $.fs.write(write.file, write.text).catch(() => undefined);
    }
  });
  return recordFlushing;
}

/**
 * Serves the FlowPlan tool: the plan itself reaches the graph as the call is
 * observed. A plugin tool's result must be text or MCP content blocks; any
 * other shape fails the call for the model, which then stops updating the plan.
 */
function serveFlowPlan(e: Record<string, unknown>): ToolCallResult {
  const steps = Array.isArray(e["steps"]) ? e["steps"].length : 0;
  const text = `Plan updated: ${steps} step(s). The person sees it as a live graph.`;
  return { result: [{ type: "text", text }], text };
}

export const register: Register = (on, options) => {
  settings = readSettings(options);
  graph = initialState({ errorThreshold: settings.errorThreshold });

  on("session.start", async ($, e, next) => {
    const result = await next(e);
    try {
      const platform = await hostPlatform($);
      const home = homeOf(await $.env.get("HOME"), await $.env.get("USERPROFILE"));
      if (home !== "") {
        flowctlDir = `${home}/.flowctl`;
        overlay = overlayClient(overlayIo($), flowctlDir, platform);
      }
      graph.sessionId ??= await $.session.id();
      terminal = await findTerminal($, platform).catch(() => undefined);
      observe($, "session.start", { input: { cwd: e.cwd } });
      await choosePlanTool($).catch(() => undefined);
      await rebuildFromTranscript($).catch(() => undefined);
      await $.command
        .register({ name: "flowctl", description: "Install, update or remove the FlowCTL overlay app", argumentHint: "init | uninstall" })
        .catch(() => undefined);
      if (overlay !== undefined) {
        started = true;
        void startOverlay($, overlay).catch(() => undefined);
      }
      void lookForNewer($).catch(() => undefined);
    } catch {
      // Without its home folder the mod still draws the status line.
    }
    return result;
  });

  on("command.run", { command: "flowctl" }, async ($, e) => {
    const { action, options } = parseArgs(e.args);
    if (action === "help") return { text: HELP };
    const ctx = await installContext($);
    const text = action === "init" ? await init(ctx, options) : await uninstall(ctx);
    if (lastSnapshot) $.ui.status(statusLine(lastSnapshot));
    return { text };
  });

  on("session.end", async ($, e, next) => {
    observe($, "session.end", { input: trim(e) });
    publish($);
    if (settings.recordEvents) {
      await flushRecording($);
    }
    return next(e);
  });

  on("prompt.submit", async ($, e, next) => {
    // Where it came from: the person (composer, bridge, sdk) or the engine
    // (a background agent's task notification, an auto-continuation...).
    const title = promptTitle(e.text);
    observe($, "prompt.submit", {
      input: { chars: e.text.length, ...(title !== undefined ? { title } : {}), ...(e.origin ? { origin: e.origin.kind } : {}) }
    });
    // Loaded again mid-session (/reload-plugins) without a session start: do the start's app check now.
    if (!started && overlay !== undefined) {
      started = true;
      void startOverlay($, overlay).catch(() => undefined);
    }
    void lookForNewer($).catch(() => undefined);
    return next(e);
  });

  on("prompt.compose", async ($, e, next) => {
    const result = await next(e);
    if (!settings.nudge) {
      return result;
    }
    return { ...result, sections: [...result.sections, { id: "flowctl-nudge", text: nudgeText(planTool), scope: "session" as const }] };
  });

  on("turn.start", async ($, e, next) => {
    const result = await next(e);
    observe($, "turn.start", { input: { turnId: e.turnId } });
    return result;
  });

  on("turn.complete", async ($, e, next) => {
    const result = await next(e);
    const { answer, ...fields } = e;
    const agents = await $.agent.list().catch(() => []);
    const summary = summarize(answer);
    observe($, "turn.complete", {
      ...(e.agentId !== undefined ? { agentId: e.agentId } : {}),
      input: { ...(trim(fields) as object), ...(summary !== undefined ? { summary } : {}) },
      result: { agents: agents.map(({ id, status, parentId, description, type }) => ({ id, status, parentId, description, type })) }
    });
    return result;
  });

  on("tool.call", async ($, e, next) => {
    const result = e.tool === FLOWPLAN_TOOL ? serveFlowPlan(e as Record<string, unknown>) : await next(e);
    const outcome = { isError: result.isError, deny: result.deny };
    const agent = e.agentId !== undefined ? { agentId: e.agentId } : {};
    if (GRAPH_TOOLS.has(e.tool)) {
      // An Agent call's prompt is the subagent's brief: code and context the
      // graph does not need. Its description names the node.
      const { tool: _tool, agentId: _agentId, prompt: _prompt, ...input } = e as typeof e & { prompt?: unknown };
      observe($, "tool.call", {
        ...agent,
        input: { tool: e.tool, ...(trim(input) as object) },
        result: { ...outcome, result: trim(result.result) }
      });
    } else {
      observe($, "tool.call", {
        ...agent,
        input: { tool: e.tool, tool_use_id: e.tool_use_id },
        result: { ...outcome, text: result.isError ? trim(result.text?.slice(0, 300)) : undefined }
      });
    }
    return result;
  });

  on("tool.check", async ($, e, next) => {
    const result = await next(e);
    // Why it asks, in words, only when it asks: the hover card shows it.
    const reason = result.decision === "ask" ? describeRequest(e.tool, e.input) : undefined;
    observe($, "tool.check", {
      ...(e.agentId !== undefined ? { agentId: e.agentId } : {}),
      input: { tool: e.tool, tool_use_id: e.tool_use_id, ceiling: e.ceiling, ...(reason !== undefined ? { reason } : {}) },
      result: { decision: result.decision, reason: result.reason, rule: result.rule }
    });
    // Still not run in a few seconds: the person is deciding (see "ask.wait" in the graph).
    if (result.decision === "ask" && e.tool !== "AskUserQuestion") {
      const call = { ...(e.agentId !== undefined ? { agentId: e.agentId } : {}), input: { tool: e.tool, tool_use_id: e.tool_use_id } };
      $.clock.after(ASK_WAIT_MS, () => observe($, "ask.wait", call));
    }
    return result;
  });

  on("agent.spawn", async ($, e, next) => {
    const result = await next(e);
    const { prompt: _prompt, ...input } = e as typeof e & { prompt?: unknown };
    observe($, "agent.spawn", { input: trim(input), result: trim(result) });
    return result;
  });

  on("classic.*", async ($, e, next) => {
    const result = await next(e);
    // classic.PreToolUse carries the bare tool call (no hook_event_name, every
    // argument): tool.call already observes what the graph needs from it.
    if (!("hook_event_name" in e)) {
      return result;
    }
    const fields = omitKeys(e, CLASSIC_DROPPED) as Record<string, unknown>;
    observe($, `classic.${String(fields["hook_event_name"])}`, { input: trim(fields) });
    if (fields["hook_event_name"] === "SessionStart" && fields["source"] === "resume") {
      await rebuildFromTranscript($).catch(() => undefined);
    }
    return result;
  });
};

files.graph/reduce.ts:
// The reducer: engine events in, graph state out. It never throws and never
// refuses an event; what does not fit becomes a warning. Every rule here is
// backed by a fixture (docs/events.md).
//
// `apply` mutates the state it is given (the caller owns it), so one event
// costs work proportional to that event, not to the session. Replaying the
// same events into a fresh state always yields the same state.

import {
  DEFAULT_ERROR_THRESHOLD,
  displayStatus,
  errorDetail,
  isStoppedByUser,
  type BaseStatus
} from "./status.ts";
import type { Attention, GraphEvent, GraphNode, SessionState } from "./types.ts";

/**
 * The mod's own plan tool, registered when the session has no task tools; the
 * engine names a plugin's tool mcp__<plugin>__<name>.
 */
export const FLOWPLAN_TOOL = "mcp__flowctl__FlowPlan";

const MAIN = "main";

interface PlanEntry {
  id: string;
  kind: "task" | "plan";
  title: string;
  activeForm?: string;
  description?: string;
  startedT?: number;
  finishedT?: number;
  base: BaseStatus;
  agentId?: string;
  blockedBy: string[];
  attention?: Attention;
  paused: boolean;
  /** Still pending when its loop's turn ended (see GraphNode.skipped). */
  skipped?: boolean;
  /** When it last became in_progress; picks the "current" task of a loop. */
  startedAt?: number;
  createdAt: number;
  /** Which of the person's requests in this session it was planned in. */
  request: number;
  lastError?: { detail: string; at: number };
}

interface AgentEntry {
  id: string;
  agentId: string;
  title: string;
  summary?: string;
  startedT: number;
  finishedT?: number;
  lastError?: { detail: string; at: number };
  state: "running" | "done" | "failed";
  parent?: string;
  attention?: Attention;
  createdAt: number;
  /** Which of the person's requests spawned it. */
  request: number;
}

/**
 * One of the person's requests (a prompt). While no plan step or subagent
 * stands for it, it is a node of its own, so every prompt leaves its mark on
 * the session's timeline.
 */
interface PromptEntry {
  id: string;
  request: number;
  /** The prompt's first line, cut short. */
  title: string;
  createdAt: number;
  startedT?: number;
  finishedT?: number;
  summary?: string;
}

interface LoopState {
  /** Consecutive tool batches that failed. */
  errorStreak: number;
  /** The current batch already counted a failure: parallel calls fail together. */
  batchFailed: boolean;
  /** A call of the current batch has returned: the loop's next check starts a new batch. */
  sawResult?: boolean;
}

export interface GraphState {
  sessionId?: string;
  cwd?: string;
  planSource: "tasks" | "flowplan" | "none";
  entries: Map<string, PlanEntry>;
  agents: Map<string, AgentEntry>;
  loops: Map<string, LoopState>;
  /** The loop (and why) of the last permission check that asked, per tool name. */
  askedBy: Map<string, { loop: string; reason?: string }>;
  /**
   * Calls put to the mode's decider and not run yet, by call id: still there
   * when the wait event comes, the person is the one deciding (see "ask.wait").
   */
  asks: Map<string, { loop: string; tool: string; reason?: string; since: number }>;
  /**
   * A classic hook event has reached the plugin: where they come (macOS), the
   * PermissionRequest hook says exactly when the person is asked, and an ask
   * alone never turns yellow. They don't come everywhere (Windows).
   */
  classicHooks: boolean;
  turn: {
    n: number;
    running: boolean;
    attention?: Attention;
    startedT?: number;
    finishedT?: number;
    summary?: string;
    lastError?: { detail: string; at: number };
  };
  /** The person's requests so far (prompt submissions); plan entries remember theirs. */
  request: number;
  /** Each request's prompt, by request number. */
  prompts: Map<number, PromptEntry>;
  /** FlowPlan step id → the node it names now (a step re-planned in a later request gets a new node). */
  steps: Map<string, string>;
  ended: boolean;
  warnings: string[];
  errorThreshold: number;
  clock: number;
}

export function initialState(options: { errorThreshold?: number } = {}): GraphState {
  return {
    planSource: "none",
    entries: new Map(),
    agents: new Map(),
    loops: new Map(),
    askedBy: new Map(),
    asks: new Map(),
    classicHooks: false,
    turn: { n: 0, running: false },
    request: 0,
    prompts: new Map(),
    steps: new Map(),
    ended: false,
    warnings: [],
    errorThreshold: options.errorThreshold ?? DEFAULT_ERROR_THRESHOLD,
    clock: 0
  };
}

/** Applies one event to `state` in place and returns it. */
export function apply(state: GraphState, event: GraphEvent): GraphState {
  state.clock += 1;
  const input = record(event.input);
  const result = record(event.result);

  if (event.event.startsWith("classic.")) {
    state.classicHooks = true;
  }
  switch (event.event) {
    case "session.start":
      state.cwd = text(input["cwd"]) ?? state.cwd;
      break;
    case "classic.SessionStart":
      if (input["source"] === "clear") {
        reset(state);
      }
      state.sessionId = text(input["session_id"]) ?? state.sessionId;
      break;
    case "session.end":
    case "classic.SessionEnd":
      // /clear ends this session too: its last snapshot must say so, or it
      // stays frozen in whatever state it had. The new one starts at the
      // SessionStart that follows (source "clear"), which resets the graph.
      state.ended = true;
      break;
    case "prompt.submit":
      // Only the person's prompts start a new request. A background agent's
      // result arrives as a submission too (origin "task-notification"), and
      // must not split the request it belongs to.
      if (isPersonPrompt(input["origin"])) onPersonPrompt(state, event, input);
      clearAttention(state, (attention) => attention.kind !== "error");
      break;
    case "turn.start":
      if (event.agentId === undefined) {
        state.turn = { n: state.turn.n + 1, running: true, startedT: event.t };
        const prompt = state.prompts.get(state.request);
        if (prompt !== undefined && prompt.startedT === undefined) prompt.startedT = event.t;
      }
      break;
    case "turn.complete":
      onTurnComplete(state, event, input, result);
      break;
    case "agent.spawn":
      onAgentSpawn(state, event, input, result);
      break;
    case "tool.check": {
      const loop = event.agentId ?? MAIN;
      const tool = text(input["tool"]) ?? "";
      const reason = text(input["reason"]);
      // Calls the model makes together are all checked before any returns; a
      // check after a result is the model's next batch (PostToolBatch, where it
      // comes, says the same; it does not come everywhere, e.g. on Windows).
      const loopState = loopOf(state, loop);
      if (loopState.sawResult) {
        loopState.batchFailed = false;
        loopState.sawResult = false;
      }
      if (result["decision"] === "ask") {
        state.askedBy.set(tool, { loop, ...(reason !== undefined ? { reason } : {}) });
        if (tool === "AskUserQuestion") {
          setAttention(state, loop, { kind: "question", detail: tool, ...(reason !== undefined ? { reason } : {}), since: event.t });
        } else {
          // "ask" puts the call to the mode's decider: the person, or in auto
          // mode a classifier that decides in moments. Yellow waits for the
          // plugin's "ask.wait", a few seconds on, if the call has not run by
          // then; the PermissionRequest hook, where it comes, says at once
          // that the person was asked.
          state.asks.set(askId(input, loop), { loop, tool, ...(reason !== undefined ? { reason } : {}), since: event.t });
        }
      } else if (tool === "AskUserQuestion" && result["decision"] !== "deny") {
        // A question waits on the person even when the permission mode lets it through unasked.
        setAttention(state, loop, { kind: "question", detail: tool, since: event.t });
      }
      break;
    }
    case "ask.wait": {
      // A call asked about a while ago has not run: the person is deciding.
      const id = askId(input, event.agentId ?? MAIN);
      const ask = state.asks.get(id);
      if (ask !== undefined && !state.classicHooks) {
        state.asks.delete(id);
        setAttention(state, ask.loop, { kind: "permission", detail: ask.tool, ...(ask.reason !== undefined ? { reason: ask.reason } : {}), since: ask.since });
      }
      break;
    }
    case "classic.PermissionRequest":
      onPermissionRequest(state, input, event.t);
      break;
    case "classic.PostToolBatch":
      // A batch of tool calls ended; its loop's next failure starts a new attempt.
      for (const loopState of state.loops.values()) {
        loopState.batchFailed = false;
        loopState.sawResult = false;
      }
      break;
    case "tool.call":
      onToolCall(state, event, input, result);
      break;
    default:
      break;
  }
  return state;
}

/** Applies every event, in order, to a fresh state. */
export function replay(events: readonly GraphEvent[], options?: { errorThreshold?: number }): GraphState {
  const state = initialState(options);
  for (const event of events) {
    apply(state, event);
  }
  return state;
}

/**
 * The nodes the state shows, in creation order: plan entries, agents, then
 * the prompts no step stands for. With none, one node for the current turn,
 * so the graph is never empty.
 */
export function nodes(state: GraphState): GraphNode[] {
  const out: GraphNode[] = [];
  const prompts = loosePrompts(state);
  const known = new Set([
    ...state.entries.keys(),
    ...[...state.agents.values()].map((agent) => agent.id),
    ...prompts.map((prompt) => prompt.id)
  ]);

  const after = sequenceLinks(state, known);
  for (const entry of [...state.entries.values()].sort(byCreation)) {
    const follows = after.get(entry.id);
    out.push({
      id: entry.id,
      kind: "task",
      title: entry.title,
      ...(entry.activeForm !== undefined ? { activeForm: entry.activeForm } : {}),
      ...(entry.description !== undefined ? { description: entry.description } : {}),
      ...(entry.startedT !== undefined ? { startedAt: entry.startedT } : {}),
      ...(entry.finishedT !== undefined ? { finishedAt: entry.finishedT } : {}),
      status: displayStatus(entry.base, entry.attention, entry.paused),
      ...(entry.attention !== undefined ? { attention: entry.attention } : {}),
      ...(entry.agentId !== undefined ? { agentId: entry.agentId } : {}),
      blockedBy: entry.blockedBy.filter((id) => known.has(id)),
      ...(follows !== undefined ? { after: follows } : {}),
      ...(entry.lastError !== undefined ? { lastError: entry.lastError } : {}),
      ...(entry.skipped === true && entry.base === "pending" ? { skipped: true } : {})
    });
  }
  for (const agent of [...state.agents.values()].sort(byCreation)) {
    const base: BaseStatus = agent.state === "running" ? "in_progress" : "completed";
    const attention: Attention | undefined =
      agent.state === "failed" ? { kind: "error", detail: "subagent failed", since: 0 } : agent.attention;
    out.push({
      id: agent.id,
      kind: "agent",
      title: agent.title,
      ...(agent.summary !== undefined ? { summary: agent.summary } : {}),
      startedAt: agent.startedT,
      ...(agent.finishedT !== undefined ? { finishedAt: agent.finishedT } : {}),
      status: agent.state === "failed" ? "error" : displayStatus(base, attention),
      ...(attention !== undefined ? { attention } : {}),
      agentId: agent.agentId,
      blockedBy: [],
      ...(after.has(agent.id) ? { after: after.get(agent.id)! } : {}),
      ...(agent.lastError !== undefined ? { lastError: agent.lastError } : {}),
      ...(agent.parent !== undefined && known.has(agent.parent) ? { parent: agent.parent } : {})
    });
  }
  // A prompt no step stands for is a node of its own: done once its request
  // is over, and the current turn while it is the latest.
  for (const prompt of prompts) {
    const follows = after.get(prompt.id);
    const current = prompt.request === state.request;
    out.push({
      ...(current ? turnFields(state) : { status: "done" as const }),
      id: prompt.id,
      kind: "turn",
      title: prompt.title,
      ...(prompt.summary !== undefined && !(current && state.turn.running) ? { summary: prompt.summary } : {}),
      ...(prompt.startedT !== undefined ? { startedAt: prompt.startedT } : {}),
      ...(prompt.finishedT !== undefined && !(current && state.turn.running) ? { finishedAt: prompt.finishedT } : {}),
      blockedBy: [],
      ...(follows !== undefined ? { after: follows } : {})
    });
  }
  // The turn node stands for the agent's work when no step does and the
  // current request has no prompt node: before the first prompt, until a new
  // request's plan arrives (hanging after the previous request's ends), and
  // whenever something needs the person while no step is in progress.
  const main = [...state.entries.values()].filter((entry) => entry.agentId === undefined);
  const currentPlanned = main.some((entry) => entry.request === state.request);
  const stepRunning = main.some((entry) => entry.base === "in_progress");
  const promptShown = prompts.some((prompt) => prompt.request === state.request);
  const showTurn =
    state.turn.n > 0 &&
    !promptShown &&
    (out.length === 0 || (state.turn.running && !currentPlanned) || (state.turn.attention !== undefined && !stepRunning));
  if (showTurn) {
    const ends = out.length > 0 ? lastEnds(steps(state, known)) : [];
    out.push({
      ...turnFields(state),
      id: `turn:${state.turn.n}`,
      kind: "turn",
      ...(ends.length > 0 ? { after: ends } : {}),
      title: "Current turn",
      ...(state.turn.summary !== undefined ? { summary: state.turn.summary } : {}),
      ...(state.turn.startedT !== undefined ? { startedAt: state.turn.startedT } : {}),
      ...(state.turn.finishedT !== undefined ? { finishedAt: state.turn.finishedT } : {}),
      blockedBy: []
    });
  }
  return out;
}

/** What the current turn shows: its status, why it needs the person, its last error. */
function turnFields(state: GraphState): Pick<GraphNode, "status" | "attention" | "lastError"> {
  return {
    // A turn that ended on errors stays red until the next turn starts.
    status:
      state.turn.attention?.kind === "error"
        ? "error"
        : displayStatus(state.turn.running ? "in_progress" : "completed", state.turn.attention),
    ...(state.turn.attention !== undefined ? { attention: state.turn.attention } : {}),
    ...(state.turn.lastError !== undefined ? { lastError: state.turn.lastError } : {})
  };
}

/**
 * The prompts no plan step or subagent stands for, once their turn started
 * (a replayed one has finished). A request with steps is drawn by its steps.
 */
function loosePrompts(state: GraphState): PromptEntry[] {
  const covered = new Set<number>();
  for (const entry of state.entries.values()) {
    if (entry.agentId === undefined) covered.add(entry.request);
  }
  for (const agent of state.agents.values()) covered.add(agent.request);
  return [...state.prompts.values()]
    .filter((prompt) => prompt.startedT !== undefined && !covered.has(prompt.request))
    .sort((a, b) => a.request - b.request);
}

export function sessionState(state: GraphState): SessionState {
  if (state.ended) {
    return "ended";
  }
  const shown = nodes(state);
  // Only a real request (a permission, a question) makes the session wait for
  // the person. Claude idling for the next prompt (Notification idle_prompt)
  // is a resting session: other sessions may take the view, and the overlay
  // may hide after a while.
  if (shown.some((node) => node.status === "needs_you")) {
    return "waiting_you";
  }
  if (state.turn.running || [...state.agents.values()].some((agent) => agent.state === "running")) {
    return "working";
  }
  return "idle";
}

/** The person's own prompts; recordings from before the origin was kept count as theirs. */
const PERSON_ORIGINS = new Set(["composer", "bridge", "sdk", "channel"]);

function isPersonPrompt(origin: unknown): boolean {
  return typeof origin !== "string" || PERSON_ORIGINS.has(origin);
}

/** A node in the session's timeline: a main-loop step, or a subagent under no step. */
interface Step {
  id: string;
  request: number;
  blockedBy: readonly string[];
  createdAt: number;
}

/**
 * The timeline's steps: the main loop's plan entries, the subagents that
 * hang under no step (spawned without a plan), which stand for their request
 * the way its steps would, and the prompts nothing else stands for. A
 * subagent under a step follows that step instead.
 */
function steps(state: GraphState, known: ReadonlySet<string>): Step[] {
  const main: Step[] = [...state.entries.values()].filter((entry) => entry.agentId === undefined);
  const loose: Step[] = [...state.agents.values()]
    .filter((agent) => agent.parent === undefined || !known.has(agent.parent))
    .map((agent) => ({ id: agent.id, request: agent.request, blockedBy: [], createdAt: agent.createdAt }));
  const prompts: Step[] = loosePrompts(state).map((prompt) => ({
    id: prompt.id,
    request: prompt.request,
    blockedBy: [],
    createdAt: prompt.createdAt
  }));
  return [...main, ...loose, ...prompts];
}

/** The steps that end the latest request with any: nothing in it depends on them. */
function lastEnds(all: readonly Step[]): string[] {
  if (all.length === 0) return [];
  const latest = Math.max(...all.map((step) => step.request));
  const group = all.filter((step) => step.request === latest);
  const needed = new Set(group.flatMap((step) => step.blockedBy));
  return group.filter((step) => !needed.has(step.id)).sort(byCreation).map((step) => step.id);
}

/**
 * One session, one graph: the first steps of each request come after the last
 * steps of the request before it, so the requests read left to right in the
 * order they were made. Steps with no dependency inside their request start
 * it; steps nothing in their request depends on end it.
 */
function sequenceLinks(state: GraphState, known: ReadonlySet<string>): Map<string, string[]> {
  const byRequest = new Map<number, Step[]>();
  for (const step of steps(state, known)) {
    byRequest.set(step.request, [...(byRequest.get(step.request) ?? []), step]);
  }
  const links = new Map<string, string[]>();
  let previous: Step[] | undefined;
  for (const request of [...byRequest.keys()].sort((a, b) => a - b)) {
    const entries = (byRequest.get(request) ?? []).sort(byCreation);
    const ids = new Set(entries.map((entry) => entry.id));
    if (previous !== undefined) {
      const needed = new Set(previous.flatMap((entry) => entry.blockedBy));
      const ends = previous.filter((entry) => !needed.has(entry.id)).map((entry) => entry.id);
      for (const entry of entries) {
        if (!entry.blockedBy.some((id) => ids.has(id))) links.set(entry.id, ends);
      }
    }
    previous = entries;
  }
  return links;
}

// --- events -----------------------------------------------------------------

function onToolCall(state: GraphState, event: GraphEvent, input: Record<string, unknown>, result: Record<string, unknown>): void {
  const tool = text(input["tool"]) ?? "";
  const loop = event.agentId ?? MAIN;
  const isError = result["isError"] === true;
  const denied = result["deny"] !== undefined;
  const errorText = text(result["text"]);

  // The call a permission prompt held has now run, or been refused.
  clearAttention(state, (attention) => attention.kind !== "error", loop);
  if (loop === MAIN) {
    for (const entry of state.entries.values()) {
      entry.paused = false;
    }
  }

  state.asks.delete(askId(input, loop));
  loopOf(state, loop).sawResult = true;
  if (isError && !denied && !isStoppedByUser(errorText)) {
    // Calls the model makes in parallel (three Reads of guessed paths) fail
    // as one attempt: a batch counts once toward the streak.
    const loopState = loopOf(state, loop);
    if (!loopState.batchFailed) {
      loopState.errorStreak += 1;
      loopState.batchFailed = true;
    }
    // Every error flashes the node it happened on; a streak turns it red for good.
    target(state, loop).lastError = { detail: errorDetail(errorText), at: event.t };
    if (loopState.errorStreak >= state.errorThreshold) {
      setAttention(state, loop, { kind: "error", detail: errorDetail(errorText), since: event.t });
    }
  } else if (!isError) {
    loopOf(state, loop).errorStreak = 0;
    clearAttention(state, (attention) => attention.kind === "error", loop);
  }

  if (isError || denied) {
    return;
  }
  const payload = record(result["result"]);
  switch (tool) {
    case "TaskCreate":
      onTaskCreate(state, event, input, payload);
      break;
    case "TaskUpdate":
      onTaskUpdate(state, event, input, payload);
      break;
    case "TaskList":
      onTaskList(state, event, payload);
      break;
    case "TaskGet":
      if (isRecord(payload["task"])) {
        upsertTask(state, event, payload["task"]);
      }
      break;
    case FLOWPLAN_TOOL:
      onFlowPlan(state, event, input);
      break;
    default:
      break;
  }
}

function onTaskCreate(state: GraphState, event: GraphEvent, input: Record<string, unknown>, payload: Record<string, unknown>): void {
  const task = record(payload["task"]);
  const taskId = text(task["id"]);
  if (taskId === undefined) {
    state.warnings.push(`TaskCreate without an id (seq ${event.seq ?? "?"})`);
    return;
  }
  state.planSource = "tasks";
  const id = `task:${taskId}`;
  const activeForm = text(input["activeForm"]);
  const description = text(input["description"]);
  state.entries.set(id, {
    id,
    kind: "task",
    title: text(task["subject"]) ?? text(input["subject"]) ?? id,
    ...(activeForm !== undefined ? { activeForm } : {}),
    ...(description !== undefined ? { description } : {}),
    base: "pending",
    ...(event.agentId !== undefined ? { agentId: event.agentId } : {}),
    blockedBy: [],
    paused: false,
    createdAt: state.clock,
    request: state.request
  });
}

function onTaskUpdate(state: GraphState, event: GraphEvent, input: Record<string, unknown>, payload: Record<string, unknown>): void {
  if (payload["success"] === false) {
    return;
  }
  const taskId = text(input["taskId"]);
  if (taskId === undefined) {
    return;
  }
  const id = `task:${taskId}`;
  const entry = state.entries.get(id);
  if (entry === undefined) {
    state.warnings.push(`TaskUpdate for unknown task ${taskId}`);
    return;
  }
  const status = input["status"];
  if (status === "deleted") {
    removeEntry(state, id);
    return;
  }
  if (status === "pending" || status === "in_progress" || status === "completed") {
    setBase(state, entry, status, event.t);
  }
  entry.title = text(input["subject"]) ?? entry.title;
  entry.activeForm = text(input["activeForm"]) ?? entry.activeForm;
  entry.description = text(input["description"]) ?? entry.description;
  for (const blocker of strings(input["addBlockedBy"])) {
    addEdge(entry, `task:${blocker}`);
  }
  for (const blocked of strings(input["addBlocks"])) {
    const target = state.entries.get(`task:${blocked}`);
    if (target !== undefined) {
      addEdge(target, id);
    }
  }
}

function onTaskList(state: GraphState, event: GraphEvent, payload: Record<string, unknown>): void {
  if (!Array.isArray(payload["tasks"])) {
    return;
  }
  state.planSource = "tasks";
  const listed = new Set<string>();
  for (const task of payload["tasks"]) {
    if (isRecord(task)) {
      const id = upsertTask(state, event, task);
      if (id !== undefined) {
        listed.add(id);
      }
    }
  }
  // The list is the whole truth: tasks it no longer has were deleted.
  for (const id of [...state.entries.keys()]) {
    if (id.startsWith("task:") && !listed.has(id)) {
      removeEntry(state, id);
    }
  }
}

/** Creates or corrects a task from a TaskList / TaskGet record. */
function upsertTask(state: GraphState, event: GraphEvent, task: Record<string, unknown>): string | undefined {
  const taskId = text(task["id"]);
  if (taskId === undefined) {
    return undefined;
  }
  const id = `task:${taskId}`;
  let entry = state.entries.get(id);
  if (entry === undefined) {
    entry = { id, kind: "task", title: id, base: "pending", blockedBy: [], paused: false, createdAt: state.clock, request: state.request };
    state.entries.set(id, entry);
  }
  entry.title = text(task["subject"]) ?? entry.title;
  const status = task["status"];
  if (status === "pending" || status === "in_progress" || status === "completed") {
    setBase(state, entry, status, event.t);
  }
  if (Array.isArray(task["blockedBy"])) {
    entry.blockedBy = strings(task["blockedBy"]).map((blocker) => `task:${blocker}`);
  }
  return id;
}

/**
 * FlowPlan: `{ steps: [{ id, title, blockedBy?, status? }] }`, each step
 * created or updated by id. Steps left out are kept.
 */
function onFlowPlan(state: GraphState, event: GraphEvent, input: Record<string, unknown>): void {
  if (!Array.isArray(input["steps"])) {
    return;
  }
  state.planSource = "flowplan";
  for (const step of input["steps"]) {
    if (!isRecord(step)) {
      continue;
    }
    const stepId = text(step["id"]);
    if (stepId === undefined) {
      continue;
    }
    // A step finished in an earlier request and planned again (to run, or with
    // new dependencies) is new work: "run the tests" again. It gets its own
    // node instead of pulling the old one forward, which would tie the
    // requests in a loop.
    let id = state.steps.get(stepId) ?? `plan:${stepId}`;
    const earlier = state.entries.get(id);
    const replanned =
      earlier !== undefined &&
      earlier.request < state.request &&
      earlier.base === "completed" &&
      (step["status"] === "pending" || step["status"] === "in_progress" || Array.isArray(step["blockedBy"]));
    if (replanned) {
      id = `plan:${stepId}#${state.request}`;
    }
    state.steps.set(stepId, id);
    let entry = state.entries.get(id);
    if (entry === undefined) {
      entry = {
        id,
        kind: "plan",
        title: id,
        base: "pending",
        ...(event.agentId !== undefined ? { agentId: event.agentId } : {}),
        blockedBy: [],
        paused: false,
        createdAt: state.clock,
    request: state.request
      };
      state.entries.set(id, entry);
    }
    entry.title = text(step["title"]) ?? entry.title;
    entry.description = text(step["description"]) ?? entry.description;
    const status = step["status"];
    if (status === "pending" || status === "in_progress" || status === "completed") {
      setBase(state, entry, status, event.t);
    }
    if (Array.isArray(step["blockedBy"])) {
      entry.blockedBy = strings(step["blockedBy"]).map((blocker) => state.steps.get(blocker) ?? `plan:${blocker}`);
    }
  }
}

function onAgentSpawn(state: GraphState, event: GraphEvent, input: Record<string, unknown>, result: Record<string, unknown>): void {
  const agentId = text(result["agentId"]);
  if (agentId === undefined) {
    return;
  }
  const title = text(input["description"]) ?? "subagent";
  const parent = parentFor(state, title);
  state.agents.set(agentId, {
    id: `agent:${agentId}`,
    agentId,
    title,
    state: "running",
    startedT: event.t,
    ...(parent !== undefined ? { parent } : {}),
    createdAt: state.clock,
    request: state.request
  });
}

function onTurnComplete(
  state: GraphState,
  event: GraphEvent,
  input: Record<string, unknown>,
  result: Record<string, unknown>
): void {
  const agentId = event.agentId;
  // The engine's own list is the authority on subagents.
  if (Array.isArray(result["agents"])) {
    for (const info of result["agents"]) {
      const agent = isRecord(info) ? state.agents.get(text(info["id"]) ?? "") : undefined;
      if (agent === undefined) {
        continue;
      }
      if (info["status"] === "completed" && agent.state === "running") {
        agent.state = "done";
        agent.finishedT = event.t;
      } else if ((info["status"] === "failed" || info["status"] === "killed") && agent.state === "running") {
        agent.state = "failed";
        agent.finishedT = event.t;
      }
    }
  }

  const summary = text(input["summary"]);
  if (agentId !== undefined) {
    const agent = state.agents.get(agentId);
    if (agent !== undefined) {
      if (agent.state === "running") {
        agent.state = "done";
        agent.finishedT = event.t;
      }
      agent.summary = summary ?? agent.summary;
    }
    skipUnstarted(state, agentId);
    return;
  }

  state.turn.running = false;
  state.turn.finishedT = event.t;
  if (summary !== undefined) {
    state.turn.summary = summary;
  }
  const prompt = state.prompts.get(state.request);
  if (prompt !== undefined) {
    prompt.finishedT = event.t;
    prompt.summary = summary ?? prompt.summary;
  }
  // The main loop stopped: a step it left in_progress is not running any
  // more, whether the turn was aborted with Esc or ended without the agent
  // updating its plan. It runs again with the loop's next tool call.
  for (const entry of state.entries.values()) {
    if (entry.base === "in_progress" && entry.agentId === undefined) {
      entry.paused = true;
    }
  }
  skipUnstarted(state, undefined);
  // Whatever the main loop had asked about is settled once its turn ends.
  for (const [id, ask] of state.asks) {
    if (ask.loop === MAIN) state.asks.delete(id);
  }
  const reason = input["reason"];
  if (reason === "aborted") {
    // Esc: what was running stops, it did not fail.
    clearAttention(state, () => true, MAIN);
  } else if (reason === "error" || reason === "refusal") {
    setAttention(state, MAIN, { kind: "error", detail: `turn ended: ${String(reason)}`, since: event.t });
  } else {
    clearAttention(state, (attention) => attention.kind !== "error", MAIN);
  }
}

function onPersonPrompt(state: GraphState, event: GraphEvent, input: Record<string, unknown>): void {
  // Typed while a turn runs, it reaches the model inside that turn: the
  // request before it is over, and this one is already under way.
  const before = state.prompts.get(state.request);
  if (state.turn.running && before !== undefined && before.finishedT === undefined) before.finishedT = event.t;
  state.request += 1;
  // Recordings from before prompts had titles keep the single turn node.
  const title = text(input["title"]);
  if (title === undefined) return;
  const prompt: PromptEntry = { id: `prompt:${state.request}`, request: state.request, title, createdAt: state.clock };
  if (state.turn.running) prompt.startedT = event.t;
  // Replayed from the transcript: that request was over before the mod started.
  if (input["replayed"] === true) {
    prompt.startedT = event.t;
    prompt.finishedT = event.t;
  }
  state.prompts.set(state.request, prompt);
}

function onPermissionRequest(state: GraphState, input: Record<string, unknown>, t: number): void {
  const tool = text(input["tool_name"]) ?? "tool";
  const asked = state.askedBy.get(tool);
  setAttention(state, asked?.loop ?? MAIN, {
    kind: tool === "AskUserQuestion" ? "question" : "permission",
    detail: tool,
    ...(asked?.reason !== undefined ? { reason: asked.reason } : {}),
    since: t
  });
}

// --- helpers ----------------------------------------------------------------

function reset(state: GraphState): void {
  const fresh = initialState({ errorThreshold: state.errorThreshold });
  Object.assign(state, fresh, { cwd: state.cwd, clock: state.clock });
}

/** The node a loop is working on: its latest in_progress entry, its agent node, or the turn. */
function target(state: GraphState, loop: string): PlanEntry | AgentEntry | GraphState["turn"] {
  let current: PlanEntry | undefined;
  for (const entry of state.entries.values()) {
    const owner = entry.agentId ?? MAIN;
    if (owner === loop && entry.base === "in_progress" && (current === undefined || (entry.startedAt ?? 0) >= (current.startedAt ?? 0))) {
      current = entry;
    }
  }
  if (current !== undefined) {
    return current;
  }
  const agent = loop === MAIN ? undefined : state.agents.get(loop);
  return agent ?? state.turn;
}

function setAttention(state: GraphState, loop: string, attention: Attention): void {
  target(state, loop).attention = attention;
}

/**
 * Clears matching attention. With `loop`, only on nodes that loop owns: its
 * entries, its agent node (an agent's own id names its loop), or the turn
 * for the main loop.
 */
function clearAttention(state: GraphState, match: (attention: Attention) => boolean, loop?: string): void {
  const holders: Array<{ attention?: Attention; agentId?: string }> = [
    ...state.entries.values(),
    ...state.agents.values()
  ];
  for (const holder of holders) {
    if (holder.attention !== undefined && match(holder.attention) && (loop === undefined || (holder.agentId ?? MAIN) === loop)) {
      delete holder.attention;
    }
  }
  if (state.turn.attention !== undefined && match(state.turn.attention) && (loop === undefined || loop === MAIN)) {
    delete state.turn.attention;
  }
}

/**
 * A loop's turn ended: the steps of its plan it never started were left
 * undone. They stay in the graph, as skipped, until the agent starts them or
 * declares them again.
 */
function skipUnstarted(state: GraphState, agentId: string | undefined): void {
  for (const entry of state.entries.values()) {
    if (entry.base === "pending" && entry.startedT === undefined && entry.agentId === agentId) {
      entry.skipped = true;
    }
  }
}

/** A call's id for `asks`: its tool_use_id, else its loop and tool. */
function askId(input: Record<string, unknown>, loop: string): string {
  return text(input["tool_use_id"]) ?? `${loop}:${text(input["tool"]) ?? ""}`;
}

function setBase(state: GraphState, entry: PlanEntry, base: BaseStatus, t: number): void {
  if (base === "in_progress" && entry.base !== "in_progress") {
    entry.startedAt = state.clock;
    entry.startedT = t;
  }
  if (base !== "pending" && entry.base !== base) {
    // A step only starts (or finishes) once what it waits on is done. A
    // blocker the agent left "in progress" (it moved on without marking it)
    // is done by now.
    for (const id of entry.blockedBy) {
      const blocker = state.entries.get(id);
      if (blocker !== undefined && blocker.base === "in_progress") {
        setBase(state, blocker, "completed", t);
      }
    }
    // Work on a later request means the main agent moved on: a step of an
    // earlier one it left "in progress" (never marked) is done by now too,
    // or it would turn blue again with every call of every later request.
    if (entry.agentId === undefined) {
      for (const other of state.entries.values()) {
        if (other.agentId === undefined && other.base === "in_progress" && other.request < entry.request) {
          setBase(state, other, "completed", t);
        }
      }
    }
  }
  if (base === "completed" && entry.base !== "completed") {
    entry.finishedT = t;
  }
  entry.base = base;
  entry.paused = false;
  delete entry.skipped;
  if (base === "completed") {
    delete entry.attention;
  }
}

function removeEntry(state: GraphState, id: string): void {
  state.entries.delete(id);
  for (const entry of state.entries.values()) {
    entry.blockedBy = entry.blockedBy.filter((blocker) => blocker !== id);
  }
}

function addEdge(entry: PlanEntry, blocker: string): void {
  if (blocker !== entry.id && !entry.blockedBy.includes(blocker)) {
    entry.blockedBy.push(blocker);
  }
}

/**
 * The task a new subagent works for, among the main loop's in-progress
 * entries: the one whose title shares the most words with the agent's
 * description ("Testes node:test para cart" → "Testes do cart"); on a tie, or
 * with no word in common, the one with the fewest subagents so far, then the
 * one started last.
 */
function parentFor(state: GraphState, description: string): string | undefined {
  const wanted = words(description);
  const helpers = new Map<string, number>();
  for (const agent of state.agents.values()) {
    if (agent.parent !== undefined) helpers.set(agent.parent, (helpers.get(agent.parent) ?? 0) + 1);
  }
  let best: { entry: PlanEntry; score: number } | undefined;
  for (const entry of state.entries.values()) {
    if (entry.agentId !== undefined || entry.base !== "in_progress") continue;
    const own = words(`${entry.title} ${entry.description ?? ""}`);
    const score = [...wanted].filter((word) => own.has(word)).length;
    if (best === undefined || isBetterParent(entry, score, best, helpers)) best = { entry, score };
  }
  return best?.entry.id;
}

function isBetterParent(
  entry: PlanEntry,
  score: number,
  best: { entry: PlanEntry; score: number },
  helpers: ReadonlyMap<string, number>
): boolean {
  if (score !== best.score) return score > best.score;
  const load = helpers.get(entry.id) ?? 0;
  const bestLoad = helpers.get(best.entry.id) ?? 0;
  if (load !== bestLoad) return load < bestLoad;
  return (entry.startedAt ?? 0) >= (best.entry.startedAt ?? 0);
}

// Words too common in step titles to tell steps apart.
const FILLER = new Set(["the", "and", "for", "with", "from", "into", "para", "com", "dos", "das", "uma", "por", "que", "test", "tests", "node"]);

function words(text: string): Set<string> {
  return new Set(
    text
      .toLowerCase()
      .split(/[^\p{L}\p{N}]+/u)
      .filter((word) => word.length >= 3 && !FILLER.has(word))
  );
}

function loopOf(state: GraphState, loop: string): LoopState {
  let found = state.loops.get(loop);
  if (found === undefined) {
    found = { errorStreak: 0, batchFailed: false };
    state.loops.set(loop, found);
  }
  return found;
}

function byCreation(left: { createdAt: number }, right: { createdAt: number }): number {
  return left.createdAt - right.createdAt;
}

function record(value: unknown): Record<string, unknown> {
  return isRecord(value) ? value : {};
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function text(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function strings(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

