// Which system the mod runs on, as far as it needs to know: macOS and
// Windows have an overlay app; anything else (Linux, for now) does not.

export type Platform = "darwin" | "win32" | "other";

/** Windows sets OS to Windows_NT; elsewhere `uname -s` names the system. */
export function platformOf(osVariable: string | undefined, uname: string): Platform {
  if (osVariable === "Windows_NT") return "win32";
  return uname.trim() === "Darwin" ? "darwin" : "other";
}

/** The person's home folder: HOME, else USERPROFILE (Windows). */
export function homeOf(home: string | undefined, userProfile: string | undefined): string {
  return home || userProfile || "";
}

files.live/rebuild.ts:
// Rebuilds a session's graph from its transcript, for when the mod starts
// late: a reload of the mod, a resumed session, an update mid-session. The
// transcript keeps every tool call and its result, so the plan (tasks,
// FlowPlan steps, subagents) can be replayed; what was only momentary (a
// permission prompt, an error streak) is not, and need not be.

import type { GraphEvent } from "../graph/types.ts";
import { promptTitle } from "./present.ts";

/** The part of a transcript message the rebuild reads ($.session.messages()). */
export interface TranscriptMessage {
  role: "user" | "assistant";
  /** The message's text blocks joined; a person's prompt has some. */
  text?: string;
  toolUses: ReadonlyArray<{ tool: string; input: Record<string, unknown>; result?: unknown; isError?: true; text?: string }>;
  /** A user message carrying tool results is the engine's, not the person's. */
  toolResults?: readonly unknown[];
}

/** The part of $.agent.list() the rebuild reads. */
export interface AgentStatusRow {
  id: string;
  status: string;
  description?: string;
}

const PLAN_TOOLS = new Set(["TaskCreate", "TaskUpdate", "TaskGet", "TaskList"]);

/**
 * The events that replay the plan the transcript holds, in order, stamped
 * `at`. Agents the engine still lists get their live status; others are done.
 */
export function rebuildEvents(
  messages: readonly TranscriptMessage[],
  options: { flowPlanTool: string; agents?: readonly AgentStatusRow[]; at: number }
): GraphEvent[] {
  const events: GraphEvent[] = [];
  const t = options.at;
  const spawned: string[] = [];

  for (const message of messages) {
    // Each of the person's prompts starts a request, so the rebuilt graph
    // keeps its requests apart, in order, as the live one does; one with no
    // plan comes back as its own node, already answered.
    if (isPersonPrompt(message)) {
      const title = promptTitle(message.text!);
      events.push({
        t,
        event: "prompt.submit",
        input: { chars: message.text!.length, ...(title !== undefined ? { title } : {}), replayed: true }
      });
      continue;
    }
    if (message.role !== "assistant") continue;
    for (const use of message.toolUses) {
      // An unanswered call has not happened yet, and a failed one changed nothing.
      if (use.result === undefined || use.isError) continue;
      if (PLAN_TOOLS.has(use.tool) || use.tool === options.flowPlanTool) {
        events.push({ t, event: "tool.call", input: { tool: use.tool, ...use.input }, result: { result: use.result } });
      } else if (use.tool === "Agent") {
        const agentId = agentIdOf(use.result);
        if (agentId === undefined) continue;
        spawned.push(agentId);
        const description = typeof use.input["description"] === "string" ? use.input["description"] : undefined;
        events.push({ t, event: "agent.spawn", input: description !== undefined ? { description } : {}, result: { agentId } });
      }
    }
  }

  if (spawned.length > 0) {
    const listed = new Map((options.agents ?? []).map((row) => [row.id, row.status]));
    // turn.complete carries the engine's agent list: running ones stay running.
    events.push({
      t,
      event: "turn.complete",
      agentId: "flowctl-rebuild",
      input: { reason: "answer" },
      result: { agents: spawned.map((id) => ({ id, status: listed.get(id) ?? "completed" })) }
    });
  }
  return events;
}

/**
 * A user message the person typed: text, no tool results, and none of the
 * engine's own wrappers (task notifications, system reminders, a slash
 * command's echo, an interruption note).
 */
function isPersonPrompt(message: TranscriptMessage): boolean {
  if (message.role !== "user" || (message.toolResults?.length ?? 0) > 0) return false;
  const text = message.text?.trim() ?? "";
  return text !== "" && !text.startsWith("<") && !text.startsWith("[Request interrupted");
}

function agentIdOf(result: unknown): string | undefined {
  if (result === null || typeof result !== "object") return undefined;
  const id = (result as Record<string, unknown>)["agentId"];
  return typeof id === "string" ? id : undefined;
}

files.live/transport.ts:
// How the mod reaches the overlay app. On macOS the app listens on a Unix
// socket in ~/.flowctl. On Windows it listens on 127.0.0.1 on a port it
// picks, and writes that port with a token to ~/.flowctl/overlay.json; every
// request carries the token. The file is cached until its modification time
// changes, and a failed request re-reads it: the app may have restarted on
// another port.

import type { Platform } from "./platform.ts";

export interface OverlayInfo {
  port: number;
  token: string;
  pid: number;
  version: string;
}

export interface OverlayRequest {
  method: string;
  headers?: Record<string, string>;
  body?: string;
  socketPath?: string;
}

/** The host's HTTP and files, as a hook has them ($.http, $.fs). */
export interface OverlayIo {
  fetch: (url: string, init: OverlayRequest) => Promise<{ ok: boolean }>;
  read: (path: string) => Promise<string>;
  mtime: (path: string) => Promise<number>;
}

export interface OverlayClient {
  /** One request to the app; true when it answered (on Windows, with a 2xx). */
  request: (method: "GET" | "POST", path: string, body?: string) => Promise<boolean>;
}

/** What the app wrote to overlay.json, or undefined when it is not that. */
export function parseOverlayInfo(text: string): OverlayInfo | undefined {
  try {
    const info = JSON.parse(text) as Partial<OverlayInfo>;
    const valid = Number.isInteger(info.port) && (info.port ?? 0) > 0 && typeof info.token === "string" && info.token !== "";
    return valid ? (info as OverlayInfo) : undefined;
  } catch {
    // Not JSON yet: the app is still writing it.
    return undefined;
  }
}

/** The client for one session's ~/.flowctl folder. */
export function overlayClient(io: OverlayIo, dir: string, platform: Platform): OverlayClient {
  const file = `${dir}/overlay.json`;
  let cached: { mtime: number; info: OverlayInfo } | undefined;

  // The app's port and token: the cache while the file keeps its mtime, else
  // the file as it is now (`fresh` skips the cache).
  async function infoOf(fresh: boolean): Promise<OverlayInfo | undefined> {
    const mtime = await io.mtime(file).catch(() => undefined);
    if (mtime === undefined) {
      cached = undefined;
      return undefined;
    }
    if (!fresh && cached?.mtime === mtime) return cached.info;
    const info = parseOverlayInfo(await io.read(file).catch(() => ""));
    cached = info === undefined ? undefined : { mtime, info };
    return info;
  }

  function send(info: OverlayInfo, method: string, path: string, body: string | undefined): Promise<boolean> {
    return io
      .fetch(`http://127.0.0.1:${info.port}${path}`, {
        method,
        headers: { "X-FlowCTL-Token": info.token },
        ...(body !== undefined ? { body } : {})
      })
      .then((response) => response.ok)
      .catch(() => false);
  }

  async function sendWindows(method: string, path: string, body: string | undefined): Promise<boolean> {
    const first = await infoOf(false);
    if (first === undefined) return false;
    if (await send(first, method, path, body)) return true;
    // Retry only when the app wrote a new port or token: the same one failed.
    const second = await infoOf(true);
    if (second === undefined || (second.port === first.port && second.token === first.token)) return false;
    return send(second, method, path, body);
  }

  return {
    async request(method, path, body) {
      if (platform !== "win32") {
        // macOS: any answer counts, as the health check always did.
        return io
          .fetch(`http://overlay${path}`, { method, socketPath: `${dir}/overlay.sock`, ...(body !== undefined ? { body } : {}) })
          .then(
            () => true,
            () => false
          );
      }
      return sendWindows(method, path, body);
    }
  };
}

files.live/windows.ts:
// The Windows commands of the install flow, as argument vectors (no shell).
// PowerShell does what the Mac tools do: a version, a hash, a copy, a
// shortcut. Paths are written with backslashes, as a person sees them.

export const WIN_EXE = "FlowCTL.exe";
export const CURL = "curl.exe";
export const TAR = "tar.exe";
/** Closes the app; a failure (it is not running) is fine. */
export const KILL_APP = ["taskkill", "/IM", WIN_EXE, "/F"];

/** The release zip of a version: FlowCTL-X.Y.Z-windows-x64.zip. */
export function winZipName(version: string): string {
  return `FlowCTL-${version}-windows-x64.zip`;
}

/** A PowerShell single-quoted string: quotes doubled, so a path stays one argument. */
export function psQuote(value: string): string {
  return `'${value.replaceAll("'", "''")}'`;
}

/** One PowerShell command, with no profile and no prompts. */
export function powershell(command: string): string[] {
  return ["powershell", "-NoProfile", "-NonInteractive", "-Command", command];
}

/** Where the app is installed: %LOCALAPPDATA%\Programs\FlowCTL. */
export function installDir(localAppData: string): string {
  return `${localAppData}\\Programs\\FlowCTL`;
}

export function installedExe(localAppData: string): string {
  return `${installDir(localAppData)}\\${WIN_EXE}`;
}

/** The Start menu shortcut, in %APPDATA%. */
export function startMenuShortcut(appData: string): string {
  return `${appData}\\Microsoft\\Windows\\Start Menu\\Programs\\FlowCTL.lnk`;
}

export function versionOf(exe: string): string[] {
  return powershell(`(Get-Item -LiteralPath ${psQuote(exe)}).VersionInfo.ProductVersion`);
}

/** The SHA-256 hex digest of a file, upper case. */
export function hashOf(file: string): string[] {
  return powershell(`(Get-FileHash -Algorithm SHA256 -LiteralPath ${psQuote(file)}).Hash`);
}

export function readText(file: string): string[] {
  return powershell(`Get-Content -Raw -LiteralPath ${psQuote(file)}`);
}

export function makeDir(dir: string): string[] {
  return powershell(`New-Item -ItemType Directory -Force -Path ${psQuote(dir)} | Out-Null`);
}

/**
 * Takes the update lock: makes `dir`, failing when it is there (another
 * session is updating). A lock older than ten minutes was left by an update
 * that never finished; it is taken over.
 */
export function takeLock(dir: string): string[] {
  const d = psQuote(dir);
  return powershell(
    `if ((Test-Path -LiteralPath ${d}) -and ((Get-Item -LiteralPath ${d}).LastWriteTime -lt (Get-Date).AddMinutes(-10))) { Remove-Item -LiteralPath ${d} -Recurse -Force }; ` +
      `New-Item -ItemType Directory -Path ${d} -ErrorAction Stop | Out-Null`
  );
}

export function copyFile(from: string, to: string): string[] {
  return powershell(`Copy-Item -LiteralPath ${psQuote(from)} -Destination ${psQuote(to)} -Force`);
}

export function shortcut(lnk: string, target: string, workDir: string): string[] {
  return powershell(
    `$s = (New-Object -ComObject WScript.Shell).CreateShortcut(${psQuote(lnk)}); ` +
      `$s.TargetPath = ${psQuote(target)}; $s.WorkingDirectory = ${psQuote(workDir)}; $s.Save()`
  );
}

export function startProcess(exe: string): string[] {
  return powershell(`Start-Process -FilePath ${psQuote(exe)}`);
}

/** Removes the install folder, and the shortcut when there is one. */
export function removeInstall(dir: string, lnk: string | undefined): string[] {
  const shortcutPart = lnk === undefined ? "" : `; Remove-Item -LiteralPath ${psQuote(lnk)} -Force -ErrorAction SilentlyContinue`;
  return powershell(`Remove-Item -LiteralPath ${psQuote(dir)} -Recurse -Force${shortcutPart}`);
}

export function removeTree(dir: string): string[] {
  return removeInstall(dir, undefined);
}

/** The pid of the process that started this PowerShell: the Claude Code process. */
export function parentPid(): string[] {
  return powershell('(Get-CimInstance Win32_Process -Filter "ProcessId=$PID").ParentProcessId');
}

files.recorder/recording.ts:
// Phase 1 event recorder: pure bookkeeping, no engine calls, so node --test
// covers it. The hooks module feeds it events and writes the files it names.

export interface RecordedEvent {
  seq: number;
  t: number;
  event: string;
  agentId?: string;
  input?: unknown;
  result?: unknown;
}

export interface ChunkWrite {
  file: string;
  text: string;
}

const MAX_STRING = 2000;
const MAX_DEPTH = 6;
const MAX_ITEMS = 50;

/**
 * A copy of `value` that is safe to keep: long strings cut, deep or wide
 * structures truncated, functions and other non-JSON values dropped. Tool
 * outputs (file contents, command output) are the bulk of a session and are
 * not what the graph needs.
 */
export function trim(value: unknown, depth = 0): unknown {
  if (value === null || typeof value === "number" || typeof value === "boolean") {
    return value;
  }
  if (typeof value === "string") {
    return value.length > MAX_STRING
      ? `${value.slice(0, MAX_STRING)}…[+${value.length - MAX_STRING} chars]`
      : value;
  }
  if (typeof value !== "object" || value === undefined) {
    return undefined;
  }
  if (depth >= MAX_DEPTH) {
    return "…[depth]";
  }
  if (Array.isArray(value)) {
    const items = value.slice(0, MAX_ITEMS).map((item) => trim(item, depth + 1));
    return value.length > MAX_ITEMS ? [...items, `…[+${value.length - MAX_ITEMS} items]`] : items;
  }
  const out: Record<string, unknown> = {};
  for (const [key, item] of Object.entries(value)) {
    const kept = trim(item, depth + 1);
    if (kept !== undefined) {
      out[key] = kept;
    }
  }
  return out;
}

/**
 * A copy of `value` without the given keys, at any depth: classic events nest
 * tool payloads (PostToolBatch's `tool_calls[].tool_input`).
 */
export function omitKeys(value: unknown, keys: ReadonlySet<string>): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => omitKeys(item, keys));
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value)
        .filter(([key]) => !keys.has(key))
        .map(([key, item]) => [key, omitKeys(item, keys)])
    );
  }
  return value;
}

/**
 * Events in numbered JSONL chunks (`rec-<run>-0001.jsonl`, ...), `run` naming
 * this recording so a resumed session (same folder) never overwrites an
 * earlier one's chunks. The engine's file
 * API has no append, so each flush rewrites only the chunks touched since the
 * last one: the cost of a flush stays bounded by the chunk size.
 */
export class Recording {
  private readonly events: RecordedEvent[] = [];
  private dirtyFrom: number | undefined;
  private readonly directory: string;
  private readonly run: string;
  private readonly chunkSize: number;

  constructor(directory: string, run: string, chunkSize = 200) {
    this.directory = directory;
    this.run = run;
    this.chunkSize = chunkSize;
  }

  add(event: Omit<RecordedEvent, "seq">): RecordedEvent {
    const recorded: RecordedEvent = { seq: this.events.length + 1, ...event };
    this.events.push(recorded);
    this.dirtyFrom ??= this.events.length - 1;
    return recorded;
  }

  get size(): number {
    return this.events.length;
  }

  /** The chunk files changed since the last call, whole. */
  flush(): ChunkWrite[] {
    if (this.dirtyFrom === undefined) {
      return [];
    }
    const writes: ChunkWrite[] = [];
    const first = Math.floor(this.dirtyFrom / this.chunkSize);
    const last = Math.floor((this.events.length - 1) / this.chunkSize);
    for (let chunk = first; chunk <= last; chunk += 1) {
      const slice = this.events.slice(chunk * this.chunkSize, (chunk + 1) * this.chunkSize);
      writes.push({
        file: `${this.directory}/rec-${this.run}-${String(chunk + 1).padStart(4, "0")}.jsonl`,
        text: slice.map((event) => JSON.stringify(event)).join("\n") + "\n"
      });
    }
    this.dirtyFrom = undefined;
    return writes;
  }
}

